//! Opt-in network verification: only disposable identities and generated bytes leave the machine.
use iroh::{
    Endpoint, SecretKey,
    endpoint::{Builder, presets},
};
use peersus_core::model::{PeerId, TransferState};
use peersus_net::{
    history::History,
    network_host::{Event, NetworkHost},
    peers::Peers,
    transfer::Source,
    transport,
};
use std::{path::Path, time::Duration};

async fn endpoint(key: SecretKey) -> Endpoint {
    let endpoint = Builder::new(presets::N0)
        .secret_key(key)
        .alpns(vec![
            transport::ALPN.to_vec(),
            peersus_net::reconnect::ALPN.to_vec(),
        ])
        .clear_ip_transports()
        .portmapper_config(iroh::endpoint::PortmapperConfig::Disabled)
        .bind()
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(60), endpoint.online())
        .await
        .unwrap();
    endpoint
}

async fn host(key: SecretKey, directory: &Path) -> NetworkHost {
    NetworkHost::new(
        endpoint(key).await,
        "Disposable verification device".into(),
        Peers::open(directory.join("peers.json")).unwrap(),
        History::open(directory.join("history.json")).unwrap(),
    )
}

async fn drive(
    a: &mut NetworkHost,
    b: &mut NetworkHost,
    done: impl Fn(&NetworkHost, &NetworkHost) -> bool,
) {
    tokio::time::timeout(Duration::from_secs(90), async {
        while !done(a, b) {
            match tokio::select! { event = a.next(101) => event, event = b.next(101) => event } {
                Event::Changed => {}
                Event::Error(_) => panic!("Public relay operation failed"),
                Event::Plugin { .. } => panic!("Unexpected plugin stream"),
                Event::Picture { .. } => panic!("Unexpected picture"),
            }
        }
    })
    .await
    .unwrap();
}

#[tokio::test]
#[ignore = "contacts public relay infrastructure with disposable generated test data"]
async fn relay_only_pair_transfer_and_persistent_reconnect() {
    let directory_a = tempfile::tempdir().unwrap();
    let directory_b = tempfile::tempdir().unwrap();
    let key_a = SecretKey::generate();
    let key_b = SecretKey::generate();
    let peer_b = PeerId(key_b.public().to_string());
    let mut a = host(key_a.clone(), directory_a.path()).await;
    let mut b = host(key_b.clone(), directory_b.path()).await;
    a.join(b.invite(100).unwrap()).unwrap();
    drive(&mut a, &mut b, |a, b| {
        !a.pairing().is_empty() && !b.pairing().is_empty()
    })
    .await;
    let pa = a.pairing().remove(0);
    let pb = b.pairing().remove(0);
    assert!(a.peers().is_empty() && b.peers().is_empty());
    a.choose(&pa.id, pa.options[0]).unwrap();
    b.choose(&pb.id, pa.options[0]).unwrap();
    drive(&mut a, &mut b, |a, b| {
        a.peers().iter().any(|p| p.online) && b.peers().iter().any(|p| p.online)
    })
    .await;
    let source = directory_a.path().join("generated.bin");
    let bytes: Vec<u8> = (0..300_000).map(|i| (i % 251) as u8).collect();
    std::fs::write(&source, &bytes).unwrap();
    let destination = directory_b.path().join("received");
    std::fs::create_dir(&destination).unwrap();
    a.send(&peer_b, Source::open(&source).await.unwrap(), 101)
        .unwrap();
    drive(&mut a, &mut b, |_, b| !b.transfers().is_empty()).await;
    assert!(!destination.join("generated.bin").exists());
    b.accept(&b.transfers()[0].id, destination.clone()).unwrap();
    drive(&mut a, &mut b, |a, b| {
        a.transfers()[0].state == TransferState::Complete
            && b.transfers()[0].state == TransferState::Complete
    })
    .await;
    assert_eq!(
        std::fs::read(destination.join("generated.bin")).unwrap(),
        bytes
    );
    a.close().await;
    b.close().await;
    // Both processes lose all volatile addresses and reconnect from durable state.
    a = host(key_a, directory_a.path()).await;
    b = host(key_b, directory_b.path()).await;
    drive(&mut a, &mut b, |a, b| {
        a.peers().iter().any(|p| p.online) && b.peers().iter().any(|p| p.online)
    })
    .await;
    assert!(a.pairing().is_empty() && b.pairing().is_empty());
    assert_eq!(a.transfers()[0].state, TransferState::Complete);
    assert_eq!(b.transfers()[0].state, TransferState::Complete);
    a.close().await;
    b.close().await;
}
